-- 本地 → 服务器 MySQL 业务数据同步（幂等）
-- 生成时间：2026-11-11；源库：本地 zjaq；目标：zjaq-mysql-1 / zjaq
-- 密码仅以 scrypt 哈希搬运，文件内不含任何明文密码。
SET NAMES utf8mb4;
SET SESSION time_zone = '+08:00';
DROP TEMPORARY TABLE IF EXISTS sync_user_map;
CREATE TEMPORARY TABLE sync_user_map (local_id CHAR(36) NOT NULL PRIMARY KEY, server_id CHAR(36) NOT NULL) ENGINE=InnoDB;
START TRANSACTION;

-- 1. 登录账号（按用户名对齐；已存在则只更新密码哈希，保留服务器 user_id）
SELECT '83b99b06-cabf-4825-bc9c-306b3b100903', 'admin', 'scrypt$16384,8,1$JljLgkbq1zLg8efYuDs5fw$u3gT0K_WkZSQNg6idBm4GFHD8nCQQF4n9xVAyy0nLuq-5gEoQEQciZUr1SsitNJ2zTPXtABHW0UJjKuiUher_w', '2026-11-06 08:11:29.942000', '2026-11-06 08:11:29.942000' FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM auth_users WHERE username = 'admin');
UPDATE auth_users SET password_hash = 'scrypt$16384,8,1$JljLgkbq1zLg8efYuDs5fw$u3gT0K_WkZSQNg6idBm4GFHD8nCQQF4n9xVAyy0nLuq-5gEoQEQciZUr1SsitNJ2zTPXtABHW0UJjKuiUher_w', updated_at = '2026-11-06 08:11:29.942000' WHERE username = 'admin';
SELECT '22e7c5db-aad0-4410-8064-a71aeb31fc0e', 'biz', 'scrypt$16384,8,1$-Hbq2ErPeJUY9WX-PvmhWA$XxpQjGti13XPFOyZJ1deNKJcavWokO0T93JX-E2Pb5k7fVb-HP4d0B3Pgli5Za6bW-arNiQmg-kot85HDTgj1A', '2026-11-10 01:55:37.680000', '2026-11-10 01:55:37.680000' FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM auth_users WHERE username = 'biz');
UPDATE auth_users SET password_hash = 'scrypt$16384,8,1$-Hbq2ErPeJUY9WX-PvmhWA$XxpQjGti13XPFOyZJ1deNKJcavWokO0T93JX-E2Pb5k7fVb-HP4d0B3Pgli5Za6bW-arNiQmg-kot85HDTgj1A', updated_at = '2026-11-10 01:55:37.680000' WHERE username = 'biz';
SELECT '6b0c42b1-fedf-4b9b-9b6a-56ff40432483', 'sales1', 'scrypt$16384,8,1$Oa2NOsXHndAXtNZIDbTjTg$LyWDv692t4glJpIe25f6nVIFZCDb_fnBzKezrZuwCbNeWPLHTaTQ_Iimn8d0gIsD4x6lJNP3K6_HTDBSnTGtmw', '2026-11-06 08:18:31.918000', '2026-11-06 08:19:10.867000' FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM auth_users WHERE username = 'sales1');
UPDATE auth_users SET password_hash = 'scrypt$16384,8,1$Oa2NOsXHndAXtNZIDbTjTg$LyWDv692t4glJpIe25f6nVIFZCDb_fnBzKezrZuwCbNeWPLHTaTQ_Iimn8d0gIsD4x6lJNP3K6_HTDBSnTGtmw', updated_at = '2026-11-06 08:19:10.867000' WHERE username = 'sales1';

-- 2. 后台账号文档与身份主体索引（userId/subjectId 按 sync_user_map 改写）
SELECT 'users', m.server_id, JSON_SET('{\"userId\":\"83b99b06-cabf-4825-bc9c-306b3b100903\",\"subjectId\":\"mysql:83b99b06-cabf-4825-bc9c-306b3b100903\",\"displayName\":\"admin\",\"role\":\"ADMIN\",\"enabled\":true,\"version\":1}', '$.userId', m.server_id, '$.subjectId', CONCAT('mysql:', m.server_id)), NULL, '2026-11-06 16:11:29.898000'
FROM sync_user_map m WHERE m.local_id = '83b99b06-cabf-4825-bc9c-306b3b100903'
ON DUPLICATE KEY UPDATE payload=VALUES(payload), expires_at=VALUES(expires_at), updated_at=VALUES(updated_at);
SELECT 'subjects', SHA2(CONCAT('mysql:', m.server_id), 256), JSON_SET('{"userId":""}', '$.userId', m.server_id), NULL, '2026-11-06 16:11:29.898000'
FROM sync_user_map m WHERE m.local_id = '83b99b06-cabf-4825-bc9c-306b3b100903'
ON DUPLICATE KEY UPDATE payload=VALUES(payload), expires_at=VALUES(expires_at), updated_at=VALUES(updated_at);
SELECT 'users', m.server_id, JSON_SET('{\"username\":\"biz\",\"displayName\":\"销售\",\"role\":\"SALES\",\"enabled\":true,\"userId\":\"22e7c5db-aad0-4410-8064-a71aeb31fc0e\",\"subjectId\":\"mysql:22e7c5db-aad0-4410-8064-a71aeb31fc0e\",\"version\":1}', '$.userId', m.server_id, '$.subjectId', CONCAT('mysql:', m.server_id)), NULL, '2026-11-10 09:55:37.729000'
FROM sync_user_map m WHERE m.local_id = '22e7c5db-aad0-4410-8064-a71aeb31fc0e'
ON DUPLICATE KEY UPDATE payload=VALUES(payload), expires_at=VALUES(expires_at), updated_at=VALUES(updated_at);
