FROM sync_user_map m WHERE m.local_id = '22e7c5db-aad0-4410-8064-a71aeb31fc0e'
ON DUPLICATE KEY UPDATE payload=VALUES(payload), expires_at=VALUES(expires_at), updated_at=VALUES(updated_at);
SELECT 'users', m.server_id, JSON_SET('{\"userId\":\"6b0c42b1-fedf-4b9b-9b6a-56ff40432483\",\"subjectId\":\"mysql:6b0c42b1-fedf-4b9b-9b6a-56ff40432483\",\"displayName\":\"本地销售一\",\"role\":\"SALES\",\"enabled\":true,\"version\":3}', '$.userId', m.server_id, '$.subjectId', CONCAT('mysql:', m.server_id)), NULL, '2026-11-06 16:19:10.880000'
