ON DUPLICATE KEY UPDATE payload=VALUES(payload), expires_at=VALUES(expires_at), updated_at=VALUES(updated_at);
SELECT 'subjects', SHA2(CONCAT('mysql:', m.server_id), 256), JSON_SET('{"userId":""}', '$.userId', m.server_id), NULL, '2026-11-06 16:19:10.880000'
FROM sync_user_map m WHERE m.local_id = '6b0c42b1-fedf-4b9b-9b6a-56ff40432483'
ON DUPLICATE KEY UPDATE payload=VALUES(payload), expires_at=VALUES(expires_at), updated_at=VALUES(updated_at);

-- 3. 业务文档（产品、快照、资料、分类、配置、统计、反馈）
-- categories：4 条
ON DUPLICATE KEY UPDATE payload=VALUES(payload), expires_at=VALUES(expires_at), updated_at=VALUES(updated_at);
-- control / catalog,analytics,site-contact：3 条
ON DUPLICATE KEY UPDATE payload=VALUES(payload), expires_at=VALUES(expires_at), updated_at=VALUES(updated_at);
