-- feedback：1 条
ON DUPLICATE KEY UPDATE payload=VALUES(payload), expires_at=VALUES(expires_at), updated_at=VALUES(updated_at);

-- 4. 编号计数器（next 取服务器与本地较大值，避免重复编号）
ON DUPLICATE KEY UPDATE payload=JSON_SET(payload, '$.next', GREATEST(CAST(JSON_EXTRACT(payload,'$.next') AS UNSIGNED), CAST(JSON_EXTRACT(VALUES(payload),'$.next') AS UNSIGNED))), updated_at=VALUES(updated_at);
ON DUPLICATE KEY UPDATE payload=JSON_SET(payload, '$.next', GREATEST(CAST(JSON_EXTRACT(payload,'$.next') AS UNSIGNED), CAST(JSON_EXTRACT(VALUES(payload),'$.next') AS UNSIGNED))), updated_at=VALUES(updated_at);
ON DUPLICATE KEY UPDATE payload=JSON_SET(payload, '$.next', GREATEST(CAST(JSON_EXTRACT(payload,'$.next') AS UNSIGNED), CAST(JSON_EXTRACT(VALUES(payload),'$.next') AS UNSIGNED))), updated_at=VALUES(updated_at);
ON DUPLICATE KEY UPDATE payload=JSON_SET(payload, '$.next', GREATEST(CAST(JSON_EXTRACT(payload,'$.next') AS UNSIGNED), CAST(JSON_EXTRACT(VALUES(payload),'$.next') AS UNSIGNED))), updated_at=VALUES(updated_at);
ON DUPLICATE KEY UPDATE payload=JSON_SET(payload, '$.next', GREATEST(CAST(JSON_EXTRACT(payload,'$.next') AS UNSIGNED), CAST(JSON_EXTRACT(VALUES(payload),'$.next') AS UNSIGNED))), updated_at=VALUES(updated_at);
ON DUPLICATE KEY UPDATE payload=JSON_SET(payload, '$.next', GREATEST(CAST(JSON_EXTRACT(payload,'$.next') AS UNSIGNED), CAST(JSON_EXTRACT(VALUES(payload),'$.next') AS UNSIGNED))), updated_at=VALUES(updated_at);
ON DUPLICATE KEY UPDATE payload=JSON_SET(payload, '$.next', GREATEST(CAST(JSON_EXTRACT(payload,'$.next') AS UNSIGNED), CAST(JSON_EXTRACT(VALUES(payload),'$.next') AS UNSIGNED))), updated_at=VALUES(updated_at);

COMMIT;

