INSERT INTO documents (collection, doc_id, payload, expires_at, updated_at) VALUES
('drafts','ZJ-Y-H-A-001','{\"content\":{\"name\":\"移动设备摄像头管控系统\",\"owner\":\"徐畅\",\"model\":\"MY-ZFT\",\"productType\":\"HARDWARE\",\"ownership\":\"SELF_DEVELOPED\",\"categoryId\":\"miyi\",\"templateId\":\"device\",\"templateVersion\":1,\"aliases\":[\"手机摄像头管控\"],\"tagline\":\"应用商店可下载，管控期间手机无法拍照、录音且不可卸载。\",\"summary\":\"移动设备摄像头管控系统是中技安全专为安卓、Harmony等主流移动操作系统打造的信息安全防护工具，应用系统级服务权限融合动态二维码加密技术（AES-256加密 + 时间戳”），监听设备操作行为与应用调用逻辑，实现对人员移动设备摄像头及录音功能的实时监测与强制管控，从源头杜绝敏感信息泄露风险，为重点区域和行业提供坚实的数据安全保障。\\n\",\"audiences\":\"• 目标行业：党政机关、军工科研、公安、金融、能源、制造等对保密与合规要求较高，且设有重点管控区域的单位。\\n• 关键岗位：保密办 / 保卫处、信息中心 / 运维管理部门、行政管理及会议组织部门、访客管理与前台。\\n• 适用于：设有厂区、研发区、生产现场、机房、档案室、会议室等重点区域，存在外来访客、第三方运维或重要会议期间移动设备管控需求的使用单位。\",\"problemValues\":[{\"id\":\"4973818d-ccf0-4fbb-a31f-25fc8e4f94ce\",\"title\":\"重点区域的管控难以落地，摄像头贴纸、封签依赖入场人工检查，撕除复原无从核验，拍照动作隐蔽、难以实时发现\",\"text\":\"从\\\"管理上要求不能拍\\\"转为\\\"技术上实现拍不到\\\"，系统在出入口完成身份核验后自动下发管控策略，对系统相机及第三方应用的前后摄像头调用实施时段化拦截，离场核验后自动恢复，不依赖现场人员逐一检查与事后追责。\"},{\"id\":\"1fcdcaac-3df3-4a4e-8ba1-d11bb37d1269\",\"title\":\"录音、视频通话等行为隐蔽，可将会议内容、屏幕资料实时外传，常规管理手段既难发现也难阻断\",\"text\":\"除拍照录像外，同步限制系统录音、音视频通话，并可按区域、人员类型对各项能力模块化组合配置；保留来电去电、文字消息等基础通信功能，在落实管控的同时兼顾正常工作与来访体验。\"},{\"id\":\"0a01abf5-c0f7-4159-9166-ae288a9eacf7\",\"title\":\"短期访客与第三方运维人员流动性强，手机集中存放影响业务开展，基于底层设备权限的方案又需逐台适配、部署复杂\",\"text\":\"系统由手机端应用「来访管家」、出入口智能识别终端「智访通」及后台管理平台组成，采用\\\"一人一码、一设备、一时效\\\"的加密动态二维码完成身份核验与策略下发，形成\\\"认证—管控—通行—权限回收\\\"闭环，可与通道闸机、门禁及访客系统联动。\"}],\"features\":[{\"id\":\"a75c73f5-e7e6-45e9-b4f3-3b2dbba9ee75\",\"title\":\"敏感功能禁用\",\"text\":\"在进入单位后，相机功能(拍照、微信视频会议、腾讯会议等)将会被全部禁用，录音功能会被禁用，但是不会影响正常的运营商电话。(管控权限可自定义)\"},{\"id\":\"8d5b75bd-27d1-4ac2-802e-5e442d9093ec\",\"title\":\"违规记录上报\",\"text\":\"若尝试使用手机相机功能，系统将瞬间触发防护机制，立即弹出全屏警告提示。此界面静待1s后即恢复正常，但相机功能仍处于禁用状态。\"},{\"id\":\"64dce83b-01b9-4fc3-9774-70d9862b787a\",\"title\":\"防卸载管控\",\"text\":\"为保障管控区域内的数据安全，在整个管控期间，系统将锁定「来访管家APP」任何尝试卸载APP的操作(如长按图标、通过设置卸载等)均无法生效。\"},{\"id\":\"6e8c821e-4a54-4cce-a265-b997413342d8\",\"title\":\"人证核验\",\"text\":\"访客在扫码前，可通过公安系统认证的身份证模块及四色身份验证功能进行人证核验，系统将自建立完整的数字身份同时保障身份真实性。\"},{\"id\":\"3fae9375-128a-4ba1-8529-f1891f997eac\",\"title\":\"精准策略下发\",\"text\":\"可根据设备信息、用户身份、部门及设备信息智能匹配，为不同岗位人员或预配置设备信息下发差异化管控策略，实现精准管理。\"},{\"id\":\"5f8f2e1e-cd7c-42c0-a5bc-87c06fe52db0\",\"title\":\"可脱网离线搭建\",\"text\":\"无网络管控方案为特定场景提供了 “刚需型” 技术解决方案，轻量化部署，尤其适合对安全性、独立性和离线可靠性要求极高的行业。\"},{\"id\":\"aa843922-bb0c-48d3-a544-1e276157ec42\",\"title\":\"99%设备适配\",\"text\":\"兼容安卓/HarmonyOS及主流品牌，同时可快速接入客户现有门禁、访客、认证系统，部署成本更低。\"},{\"id\":\"2246a307-615c-4595-b65a-213d1522a626\",\"title\":\"应用商店可下载\",\"text\":\"目前来访管家APP已上架华为、小米、荣耀、 vivo、OPPO、应用宝6款应用商店，通过了官方检测，保障隐私安全，同时方便快速下载安装。\\n\"}],\"scenarios\":[{\"id\":\"fdeccd3c-fb94-4101-a9a6-e2e537044ddf\",\"title\":\"敏感与重点区域出入管理\",\"text\":\"适用于厂区、研发区、生产现场、机房、档案室、保密室、核心办公区等区域，自入厂登记处起对进出人员移动终端实施管控，可结合通道闸机完成二维码身份识别与通行授权，防范周边屏幕信息、桌面资料及现场环境被拍摄留存。\"},{\"id\":\"4158c6a0-9013-4b93-8862-18ba382858b9\",\"title\":\"第三方运维与外包服务\",\"text\":\"设备维修商、系统服务商等外部人员进入机房、服务器区域开展维护调试时，在不影响其正常作业的前提下管控敏感能力，降低关键场所设备资产信息与核心数据外泄风险。\"},{\"id\":\"aecca494-10cf-44df-9332-937be7a93ad2\",\"title\":\"重要会议与商务洽谈\",\"text\":\"董事会、股东会、战略研讨、商务谈判等场景，参会人员于会前扫码完成管控，避免采用集中收取手机、粘贴封签等方式影响会议秩序；散会后经离场核验即恢复设备功能。\"},{\"id\":\"5d21c2a9-b1b9-4cd6-863f-3226c21b7f41\",\"title\":\"楼宇访客与访客登记\",\"text\":\"结合访客登记系统，在登记后生成二维码完成身份识别与通道授权，实现访客信息与管控记录关联，便于来访统计、异常预警与事后溯源。\"},{\"id\":\"178689e1-4b7f-4a7f-be92-a1cd6f0b7bcb\",\"title\":\"高安全等级行业场景\",\"text\":\"面向党政机关、军工科研、金融、公安等对保密与合规要求较高的单位，在涉密会议、案卷与重要资料查阅、办案区域等场景提供时段化技术防护，并可通过内网部署满足独立性与离线可靠性要求。\"}],\"technical\":{},\"boundaries\":\"\",\"media\":[{\"mediaId\":\"34c90f27-4e21-4f9e-91e8-80746b55e555\",\"assetId\":\"d83e8eb5-dd13-4519-b3ad-638b4b5110f7\",\"role\":\"screenshot\",\"alt\":\"立柱机\"},{\"mediaId\":\"94fed7a0-d643-4bc2-9e1c-a3eb5dd6c924\",\"assetId\":\"6d65c174-9f78-4426-9139-06626e922aa3\",\"role\":\"screenshot\",\"alt\":\"台式机\"}],\"materials\":[{\"materialId\":\"92c5dc17-7a0e-4694-ac61-398bc6766b19\",\"versionId\":\"37ac8537-4c76-464e-9efc-5c8619b60709\",\"name\":\"移动终端敏感权限管控系统产品介绍\",\"kind\":\"presentation\",\"category\":\"promotional\",\"subCategory\":\"deck\",\"versionLabel\":\"V01.0\",\"applicableVersion\":\"\",\"sourceAssetId\":null,\"preview\":{\"kind\":\"pdf\",\"assetId\":\"f3aa34b3-b33c-42aa-ae8e-fa9f495bd229\",\"pageCount\":22}},{\"materialId\":\"8468b040-d7de-4672-a900-cb6636f11368\",\"versionId\":\"d7f37d61-cc37-4169-9671-5ea26eb281f0\",\"name\":\"移动设备摄像头管控系统-彩页\",\"kind\":\"brochure\",\"category\":\"promotional\",\"subCategory\":\"onepager\",\"versionLabel\":\"V01.0\",\"applicableVersion\":\"\",\"sourceAssetId\":null,\"preview\":{\"kind\":\"pdf\",\"assetId\":\"88a97f92-5b58-4b8c-aa32-eac5041a77af\",\"pageCount\":2}},{\"materialId\":\"a3deae4f-4377-4327-9081-9439e8a6cc40\",\"versionId\":\"a2170c7d-336a-4ae7-b0f2-3c3b00e447c7\",\"name\":\"视频介绍\",\"kind\":\"brochure\",\"category\":\"promotional\",\"subCategory\":\"video\",\"versionLabel\":\"V01.0\",\"applicableVersion\":\"\",\"sourceAssetId\":null,\"preview\":{\"kind\":\"video\",\"assetId\":\"878e7306-a612-440c-9adb-adab425f028d\",\"mimeType\":\"video/mp4\"}},{\"materialId\":\"13747aec-bfac-4f50-a816-be94251422ee\",\"versionId\":\"5aca16b4-15a0-4843-b8e4-795928671038\",\"name\":\"中技安全-移动设备摄像头管控系统用户-操作手册\",\"kind\":\"technical\",\"category\":\"technical\",\"subCategory\":\"manual\",\"versionLabel\":\"V01.0\",\"applicableVersion\":\"\",\"sourceAssetId\":null,\"preview\":{\"kind\":\"pdf\",\"assetId\":\"484303fc-49d3-4316-85b0-5166c1370b90\",\"pageCount\":33}},{\"materialId\":\"147ac4ee-deab-47cf-86ba-655a54f71dda\",\"versionId\":\"283cb1d2-ad10-47df-b429-027af0e8c566\",\"name\":\"移动设备摄像头管控系统-技术白皮书\",\"kind\":\"technical\",\"category\":\"technical\",\"subCategory\":\"whitepaper\",\"versionLabel\":\"V01.0\",\"applicableVersion\":\"\",\"sourceAssetId\":null,\"preview\":{\"kind\":\"pdf\",\"assetId\":\"5f5a0c81-3ea8-4c69-84ce-ed8d87074688\",\"pageCount\":20}},{\"materialId\":\"dd1cede3-c0f8-4809-b86f-8d02668ef379\",\"versionId\":\"f82775d0-20c9-4ecc-9416-c47f0b563de7\",\"name\":\"来访管家APP使用说明\",\"kind\":\"technical\",\"category\":\"technical\",\"subCategory\":\"manual\",\"versionLabel\":\"V01.0\",\"applicableVersion\":\"\",\"sourceAssetId\":null,\"preview\":{\"kind\":\"pdf\",\"assetId\":\"2ec5ebc1-d510-485c-9526-3fd986db1655\",\"pageCount\":2}}]},\"meta\":{\"updatedAt\":\"2026-11-10T06:38:12.246Z\",\"updatedBy\":\"83b99b06-cabf-4825-bc9c-306b3b100903\",\"unpublishedAt\":null}}',NULL,'2026-11-10 14:38:12.247000')
